proc sql;
*Lag holding;
create table dt2 as select distinct a.*,b.adj_holding as lag_holding
from dt1 as a left join wd.s2 as b
on a.final_mgrno=b.final_mgrno and a.cusip=b.cusip and a.lagqtr=b.yrqtr;

*Next holding;
create table dt2a as select distinct a.*,b.adj_holding as next_holding
from dt2 as a left join wd.s2 as b
on a.final_mgrno=b.final_mgrno and a.cusip=b.cusip and a.nextqtr=b.yrqtr;

*Lag aum;
create table dt2b as select distinct a.*,b.aum as lag_aum
from dt2a as a left join wd.aum as b
on a.final_mgrno=b.final_mgrno and a.lagqtr=b.yrqtr;

*Next aum;
create table dt2c as select distinct a.*,b.aum as next_aum
from dt2b as a left join wd.aum as b
on a.final_mgrno=b.final_mgrno and a.nextqtr=b.yrqtr;

*Lag crsp_weight;
create table dt2f as select distinct a.*,b.crsp_weight as lag_crsp_weight
from dt2e as a left join wd.crsp_weight as b
on a.permno=b.permno and a.lagqtr=b.yrqtr;

*Next crsp_weight;
create table dt2g as select distinct a.*,b.crsp_weight as next_crsp_weight
from dt2f as a left join wd.crsp_weight as b
on a.permno=b.permno and a.nextqtr=b.yrqtr;

*Lag2 crsp_weight;
create table dt2h as select distinct a.*,b.crsp_weight as lag2_crsp_weight
from dt2g as a left join wd.crsp_weight as b
on a.permno=b.permno and a.lag2qtr=b.yrqtr;
quit;

proc sql;create table dt2k as select distinct a.*,b.N_Buy,b.N_Rec
from dt2j as a left join wd.amaskcd_buy as b
on a.amaskcd=b.amaskcd and a.yr=b.annyear;quit;

proc sql;create table dt2l as select distinct a.*,b.q,b.roa,b.ior,b.shrcd,b.exchcd
from dt2k as a left join wd.Firm_Controls as b
on a.cusip=b.cusip and b.fyenddt<=a.anndats<b.next_fyenddt

/*use the most recent data*/
group by a.cusip,a.anndats having b.fyenddt=max(b.fyenddt);quit;

proc sql;create table previous_trading_day3 as select distinct a.*,abs(prc) as prc,abs(prc)*(shrout*cfacshr)/(cfacpr*1000) as mve
from previous_day2 as a left join crsp2.dsf as b
on a.permno=b.permno and a.previous_trading_day=b.date;quit;

*8.1 Obtain actual price before the announcement day - to exclude influence of penny stock;
data previous_day;set dt2m;
keep uniqueid permno anndats previous_trading_day;
previous_trading_day=anndats;
format previous_trading_day DATE9.;
run;

*Obatin the date of the previou trading day;
%previous_trading_day(inset=previous_day,outset=previous_day2,evtdate=previous_trading_day);

proc sql;create table rec2 as select distinct a.*,b.permno
from rec as a, crsp2.msenames as b
where a.cusip=b.ncusip and (b.namedt<=a.anndats<=b.nameendt);quit;
